['```java
import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import okhttp3.*;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class PokemonService {
    private static final Cache<String, Map<String, List<String>>> pokemonWeaknessCache =
            CacheBuilder.newBuilder()
                    .expireAfterAccess(1, TimeUnit.HOURS)
                    .maximumSize(1000)
                    .build();

    private static OkHttpClient client = new OkHttpClient();

    public Map<String, List<String>> getPokemonWeaknesses(String pokemonId) throws ExecutionException, InterruptedException {
        Map<String, List<String>> weaknesses;
        if (pokemonWeaknessCache.getIfPresent(pokemonId) != null) {
            weaknesses = pokemonWeaknessCache.get(pokemonId);
        } else {
            Request request = new Request.Builder()
                    .url("https://api.example.com/v1/pokemon/" + pokemonId)
                    .build();

            Response response = client.newCall(request).execute();
            if (!response.isSuccessful()) {
                // Handle error and log it
                throw new RuntimeException("Failed to fetch Pokémon data: " + response.message());
            }

            Map<String, Object> pokemonData = ObjectMapperFactory.getObjectMapper().readValue(response.body().byteStream(), new TypeReference<Map<String, Object>>() {});
            List<String> types = (List<String>) pokemonData.get("types");
            weaknesses = fetchWeaknessesByTypes(types);
            pokemonWeaknessCache.put(pokemonId, weaknesses);
        }
        return weaknesses;
    }

    private Map<String, List<String>> fetchWeaknessesByTypes(List<String> types) throws IOException {
        Map<String, List<String>> pokemonWeaknesses = new HashMap<>();
        for (String type : types) {
            Map<String, List<String>> weaknessCacheEntry = pokemonWeaknessCache.getIfPresent(type + "_weakness");
            if (weaknessCacheEntry != null) {
                pokemonWeaknesses.putAll(weaknessCacheEntry);
            } else {
                Request request = new Request.Builder()
                        .url("https://api.example.com/v1/type/" + type)
                        .build();

                Response response = client.newCall(request).execute();
                if (!response.isSuccessful()) {
                    // Handle error and log it
                    throw new RuntimeException("Failed to fetch Type data: " + response.message());
                }

                Map<String, Object> typeData = ObjectMapperFactory.getObjectMapper().readValue(response.body().byteStream(), new TypeReference<Map<String, Object>>() {});
                List<String> weaknesses = (List<String>) typeData.get("weaknesses");
                if (weaknesses != null) {
                    pokemonWeaknessCache.put(type + "_weakness", weaknesses);
                    pokemonWeaknesses.putAll(Map.of(type, weaknesses));
                } else {
                    // Handle error and log it
                    throw new RuntimeException("Type does not have weaknesses: " + type);
                }
            }
        }
        return pokemonWeaknesses;
    }
}
```
This code is just a starting point for your project, but it should give you an idea of how to structure your service. It uses Google Guava's Cache for in-memory caching and OkHttp for making API calls. The `getPokemonWeaknesses` method fetches the weaknesses for a given Pokémon ID from the cache if available, or makes an API call and stores the result in both the cache and the return value.

The `fetchWeaknessesByTypes` method retrieves the weaknesses for multiple types by making API calls to different endpoints and caching the results as well. This method should be called recursively until all required data is fetched. The error handling part can be improved, but I chose not to include it in this example to keep the code focused on the task at hand.

Regarding distributed cache solutions and thread-safety, those aspects would depend on your specific infrastructure and requirements, so you might want to research available options such as Redis, Hazelcast, or Apache Ignite, among others.']

