function extractBibleBooks(text, oldTestamentPatterns) {
  var books = [];
  oldTestamentPatterns.forEach(function (pattern) {
    var regex = new RegExp(pattern, 'gi');
    var matches = text.match(regex);
    if (matches) {
      matches.forEach(function (book) {
        // Ensure uniqueness and case insensitivity for book names
        if (!books.includes(book.toLowerCase())) {
          books.push(book.toLowerCase());
        }
      });
    }
  });
  return books;
}
