import io.micronaut.websocket.ServerWebSocket;
import reactor.util.retry.BackoffStrategy;
import reactor.util.retry.Retry;

@Factory
public class ConnectionPool {

    private static final Logger LOG = LoggerFactory.getLogger(ConnectionPool.class);
    private static final int MAX_CONNECTION_ATTEMPTS_PER_SECOND = 10_000;
    private static final int CONNECTION_VALIDATION_INTERVAL = 60;

    private final Selector selector;
    private final Map<InetSocketAddress, Connection> connections;
    private final Cache<InetSocketAddress, Connection> connectionCache;
    private final RingBuffer<ConnectionEvent> ringBuffer;
    private final EventTranslatorOneArg<ConnectionEvent, ?> eventTranslator;
    private final AsyncMessageProducer<String> messageProducer;
    private final ScheduledExecutorService scheduler;

    @Bean
    public ConnectionPool createConnectionPool(MessageChannel<String> messageChannel) {
        selector = Selector.open();
        connections = new ConcurrentSkipListSet<>();
        connectionCache = CacheBuilder.newBuilder()
                .maximumSize(Integer.MAX_VALUE)
                .expireAfterWrite(CONNECTION_VALIDATION_INTERVAL, TimeUnit.SECONDS)
                .removalListener(new RemovalListener<InetSocketAddress, Connection>() {
                    @Override
                    public void onRemoval(InetSocketAddress socketAddress, Connection oldValue, boolean evicted) {
                        LOG.debug("Connection removed: {}", socketAddress);
                        disconnect(oldValue);
                    }
                })
                .build();

        ringBuffer = createRingBuffer();
        eventTranslator = createEventTranslator();

        messageProducer = new AsyncMessageProducer<>(messageChannel);
        scheduler = Executors.newScheduledThreadPool(1);

