[' ```php
<?php

class UserPasswordUpdater {
    private $userRepository;
    private $authService;
    private $commandRunner;
    private $logger;

    public function __construct(UserRepository $userRepository, AuthService $authService, CommandRunner $commandRunner, Logger $logger) {
        $this->userRepository = $userRepository;
        $this->authService = $commandRunner;
        $this->commandRunner = $commandRunner;
        $this->logger = $logger;
    }

    public function updatePassword($userId, $password): array {
        $validPassword = $this->validatePasswordStrength($password);

        if (!$validPassword) {
            return ['status' => 'failure', 'message' => 'Invalid password'];
        }

        $lockKey = "user_password_update_{$userId}";
        Redis::lock($lockKey);

        try {
            $existingUser = $this->userRepository->findById($userId);
            if (!$existingUser) {
                throw new Exception("User not found");
            }

            // Update password in the database
            $this->userRepository->updatePassword($userId, $password);

            $responseFromAuthService = $this->authService->updatePassword($userId, $password);

            if ($responseFromAuthService['status'] === 'failure') {
                Redis::unlock($lockKey);
                return $responseFromAuthService;
            }

            // Execute command-line utility for security vulnerability check
            $commandOutput = $this->commandRunner->run("security-check", ["--app-env", getcwd()]);

            if ($commandOutput['exit_code'] !== 0) {
                Redis::unlock($lockKey);
                return ['status' => 'partial', 'message' => "Password updated but command execution failed"];
            }

            Redis::unlock($lockKey);
            $this->logger->info("Password updated successfully for user {$userId}");
            return ['status' => 'success', 'message' => "Password updated successfully"];
        } catch (Exception $e) {
            Redis::unlock($lockKey);
            $this->logger->error($e->getMessage());
            return ['status' => 'failure', 'message' => $e->getMessage()];
        }
    }

    private function validatePasswordStrength($password): bool {
        // Implement password strength validation logic here, such as checking for minimum length, special characters, and patterns.
        // This example uses a simplified regex pattern to check for at least one lowercase letter, one uppercase letter, one number, and a special character.
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $password);
    }
}
```

In this example:

