['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

typedef void (*callback_func)(const char *, size_t);

void safe_strcpy(char *dst, const char *src, size_t size) {
    strncpy(dst, src, size);
    dst[size] = '\0';
}

struct data_chunk {
    char *data;
    size_t data_len;
    size_t remaining_len;
    callback_func callback;
};

pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t data_cond = PTHREAD_COND_INITIALIZER;
static struct data_chunk *current_data = NULL;
static bool is_data_available = false;

void process_data(struct data_chunk *data) {
    // Handle the external data processing service calls here.
    // This can include logging, truncating, or storing the data externally.
}

void data_processing_thread(void *arg) {
    while (true) {
        pthread_mutex_lock(&data_mutex);

        while (!is_data_available && current_data != NULL) {
            pthread_cond_wait(&data_cond, &data_mutex);
        }

        if (current_data == NULL) {
            break;
        }

        struct data_chunk *temp = current_data;
        current_data = NULL;
        is_data_available = false;

        process_data(temp);

        free(temp->data);
        free(temp);

        pthread_mutex_unlock(&data_mutex);
    }
}

void handle_large_string(const char *input, size_t max_size, callback_func callback) {
    if (max_size == 0 || input == NULL) {
        return;
    }

    if (strlen(input) <= max_size) {
        callback(input, strlen(input));
        return;
    }

    char *chunk = malloc(max_size);
    size_t data_index = 0;
    while (data_index < strlen(input)) {
        safe_strcpy(chunk, input + data_index, max_size);

        pthread_mutex_lock(&data_mutex);
        if (current_data == NULL) {
            current_data = malloc(sizeof(struct data_chunk));
            current_data->data = chunk;
            current_data->data_len = strlen(chunk);
            current_data->remaining_len = max_size - current_data->data_len;
            current_data->callback = callback;
            is_data_available = true;
        } else {
            if (current_data->remaining_len > max_size) {
                safe_strcpy(current_data->data + current_data->data_len, chunk);
                current_data->data_len += strlen(chunk);
                current_data->remaining_len -= strlen(chunk);
            } else {
                struct data_chunk *temp = malloc(sizeof(struct data_chunk));
                temp->data = chunk;
                temp->data_len = strlen(chunk);
                temp->remaining_len = current_data->remaining_len;
                temp->callback = callback;

                pthread_mutex_lock(&data_mutex);
                if (!is_data_available) {
                    current_data->next = temp;
                } else {
                    struct data_chunk *iter = current_data;
                    while (iter->next != NULL) {
                        iter = iter->next;
                    }
                    iter->next = temp;
                }
                is_data_available = true;
                pthread_mutex_unlock(&data_mutex);
            }
        }
        data_index += max_size;
    }

    // Kick off a new thread to process the collected data.
    pthread_t processing_thread;
    pthread_create(&processing_thread, NULL, &data_processing_thread, NULL);
}

