  try {
    const file = req.file; // File details from multer
    const user = req.user; // User details from Google OAuth
    const quality = parseInt(req.query.quality || 80);

    // Cache upload metadata to reduce redundant requests
    await redisClient.setex(`upload:${file.originalname}`, 60 * 60, JSON.stringify({ user, quality }));

    const result = await cloudStorage.upload(file, quality);
    res.json(result);
