typedef struct {
    LTE_RRC_CME_CAUSE **data;
    size_t capacity;
    size_t size;
} LTE_RRC_CME_CAUSE_ARRAY;

void lte_rrc_cme_cause_array_init(LTE_RRC_CME_CAUSE_ARRAY *arr, size_t initial_capacity) {
    arr->data = malloc(initial_capacity * sizeof(LTE_RRC_CME_CAUSE*));
    if (!arr->data) exit(EXIT_FAILURE); // handle error
    arr->capacity = initial_capacity;
    arr->size = 0;
}

void lte_rrc_cme_cause_array_resize(LTE_RRC_CME_CAUSE_ARRAY *arr, size_t new_capacity) {
    if (new_capacity <= arr->size) return;

    LTE_RRC_CME_CAUSE **new_data = realloc(arr->data, new_capacity * sizeof(LTE_RRC_CME_CAUSE*));
    if (!new_data) exit(EXIT_FAILURE); // handle error
    arr->data = new_data;
    arr->capacity = new_capacity;
}
