bool validate_oauth2_token(const char *json) {
    json_t *root = json_loads(json, 0, NULL);
    if (!root) return false; // handle error

    json_t *access_token_field = json_object_get(root, "access_token");
    json_t *expires_in_field = json_object_get(root, "expires_in");
    json_t *token_type_field = json_object_get(root, "token_type");
    if (!access_token_field || !expires_in_field || !token_type_field) {
        json_decref(root);
        return false; // handle error
    }

    const char *access_token = json_string_value(access_token_field);
    int expires_in = json_integer_value(expires_in_field);
    const char *token_type = json_string_value(token_type_field);

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        json_decref(root);
        return false; // handle error
    }

    json_decref(root);
    return true;
}
