import org.apache.avro.specific.SpecificRecordBase;
import redis.clients.jedis.Jedis;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class ConditionErrorLogger {

    private static final Gson GSON = new Gson();
    private static final ActorSystem system = ActorSystem.create("ConditionErrorLogger");
    private static final ForkJoinExecutorService executor = system.dispatcher().getForkJoinExecutorService();
