import os
import subprocess
from threading import Thread
from queue import Queue
from cryptography.fernet import Fernet
import yaml
from typing import Dict, Any

class InfrastructureConfigurator:
    def __init__(self, config_manager, credential_key):
        self.config_manager = config_manager
        self.credential_key = credential_key
        self.fernet = Fernet(self.credential_key)

    def read_yaml(self, path: str) -> Dict[str, Any]:
        with open(path, 'r') as stream:
            return yaml.safe_load(stream)

    def write_yaml(self, data: Dict[str, Any], path: str):
        with open(path, "w") as outfile:
            yaml.dump(data, outfile)

    def encrypt(self, plaintext: bytes) -> bytes:
        return self.fernet.encrypt(plaintext)

    def decrypt(self, ciphertext: bytes) -> bytes:
        return self.fernet.decrypt(ciphertext)

    def replace_placeholders(self, data: Dict[str, Any]) -> None:
        for key, value in data.items():
            if isinstance(value, str) and '$' in value:
                data[key] = self.config_manager.get(value.replace('$', ''))

    def execute_shell(self, command: str) -> str:
        process = subprocess.run(command, shell=True, capture_output=True, text=True)
        return process.stdout

    def configure_file(self, file_path: str):
        config = self.read_yaml(file_path)
        self.replace_placeholders(config)
        for service, data in config.items():
            if 'credentials' in data:
                data['credentials'] = [self.encrypt(password.encode()) for password in data['credentials']]
        self.write_yaml(config, file_path)

    def process_queue(self, queue: Queue):
        while not queue.empty():
            file_path = queue.get()
            try:
                self.configure_file(file_path)
            except Exception as e:
                print(f'Error configuring {file_path}: {e}')
            finally:
                queue.task_done()

class ConfigManager:
