    configurator = InfrastructureConfigurator(config_manager, os.urandom(32))
    queue = Queue()
    for file in ['service1.yaml', 'service2.yaml', 'service3.yaml']:
        queue.put(file)

    threads = []
    for _ in range(5):  # Adjust the number of threads according to your hardware
        t = Thread(target=configurator.process_queue, args=(queue,))
        t.daemon = True
        t.start()
        threads.append(t)

    queue.join()

if __name__ == "__main__":
    main()
```
