public class ClinicService
{
    private readonly ILogger<ClinicService> _logger;
    private BinaryFormatter _binaryFormatter = new BinaryFormatter();

    public ClinicService(ILogger<ClinicService> logger)
    {
        _logger = logger;
    }

    public async Task UpdateClinicStatusAsync(int clinicId, string ipAddress)
    {
        try
        {
            using var fileStream = File.OpenRead("clinics.bin");
            var clinics = (Clinic[])_binaryFormatter.Deserialize(fileStream);
            var clinic = clinics.FirstOrDefault(c => c.Id == clinicId);

            if (clinic != null)
            {
                clinic.LastModifiedIPAddress = ipAddress;
                clinic.LastModifiedDate = DateTime.Now;
            }

            using var outputFileStream = File.Create("clinics.bin");
            _binaryFormatter.Serialize(outputFileStream, clinics);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating clinic status.");
        }
    }

    public async Task CheckAndUpdateApiAsync()
    {
        try
        {
            // API interaction code here...

            if (apiResponseStatus == 200)
            {
                await UpdateClinicStatusAsync(clinicId, _ipAddress);
            }
            else
            {
                _logger.LogInformation("API response status: {ApiResponseStatus}. Not updating clinic status.", apiResponseStatus);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error interacting with API.");
        }
    }
}
```

