#[macro_use] extern crate llvm_ir;
extern crate ir_parser;

use std::fs::File;
use std::io::{BufRead, BufReader};
use ir_parser::Parser;

fn parse_llvm(filePath: &str) -> String {
    let file = File::open(filePath).unwrap();
    let reader = BufReader::new(file);
    let mut parser = Parser::new();
    let mut llvm_ir = String::new();
    for line in reader.lines() {
        let line = line.unwrap();
        // Debugging statements to log parsed nodes and the generated LLVM IR code during development
        println!("{:?}", line);
        let ast = parser.parse(line).unwrap();
        llvm_ir += &ast.to_string();
    }
    llvm_ir
}
```

