[' ```c
#include <arpa/inet.h>
#include <getopt.h>
#include <iostream>
#include <fstream>
#include <functional>
#include <map>
#include <mutex>
#include <sstream>
#include <string>
#include <system_error>
#include <thread>
#include <vector>

using LineCallback = std::function<void(const std::string&)>;

struct Stats {
    size_t lineCount = 0;
    size_t charCount = 0;
};

std::mutex statsMutex;
Stats globalStats;

void incrementStats(const std::string& line) {
    std::lock_guard<std::mutex> lock(statsMutex);
    ++globalStats.lineCount;
    globalStats.charCount += line.length();
}

// Health check integration (to be implemented)
void reportHealthCheck() { /* ... */ }

void processLines(const std::string& filename, LineCallback callback, size_t limit = numeric_limits<size_t>::max()) {
    // Threaded processing
    if (std::thread::hardware_concurrency() > 1) {
        std::vector<std::thread> threads;
        size_t chunkSize = static_cast<size_t>(std::ceil(static_cast<float>(limit) / static_cast<float>(std::thread::hardware_concurrency())));
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::system_error(errno, std::generic_category(), "Failed to open file: " + filename);
        }
        size_t position = 0;

        for (auto& thread : threads) {
            thread = std::thread([&]() {
                std::string buffer;
                while (true) {
                    if (position >= limit || !file.is_open()) break;
                    if (!getline(file, buffer)) break;
                    position += buffer.length();
                    incrementStats(buffer);
                    callback(buffer);
                }
            });
            threads.back().detach();
        }

        for (auto& thread : threads) {
            thread.join();
        }
    } else {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::system_error(errno, std::generic_category(), "Failed to open file: " + filename);
        }
        std::string buffer;
        while (getline(file, buffer)) {
            incrementStats(buffer);
            callback(buffer);
        }
    }
}

void displayUsage() {
    std::cout << "Usage: my_utility [options] input_file\n";
    std::cout << "Options:\n";
    std::cout << "-h, --help                  Display this help message and exit.\n";
    std::cout << "--manpage                   Display detailed manual page.\n";
    std::cout << "-cs                         Count only non-empty lines.\n";
    std::cout << "-o output_file              Redirect output to a specified file.\n";
    std::cout << "-l limit                    Limit the number of lines processed (useful for testing).\n";
    std::cout << "-v                          Enable verbose mode to display additional statistics.\n";
}

int main(int argc, char* argv[]) {
    bool countOnlyNonEmptyLines = false;
    bool enableVerboseMode = false;
    size_t limit = numeric_limits<size_t>::max();
    std::string outputFile;
    bool showManPage = false;

    const char* shortOptions = "hvo:l:cs";
    const struct option longOptions[] = {{"help", no_argument, nullptr, 'h'},
                                         {"manpage", no_argument, nullptr, 'm'},
                                         {"count-only-nonempty", no_argument, nullptr, 'c'},
                                         {"verbose", no_argument, nullptr, 'v'},
                                         {"limit", required_argument, nullptr, 'l'},
                                         {"output", required_argument, nullptr, 'o'},
                                         {nullptr, 0, nullptr, 0}};

    int optionIndex = 0;
    while (true) {
        int opt = getopt_long(argc, argv, shortOptions, longOptions, &optionIndex);
        if (opt == -1) break;

        switch (opt) {
            case 'h':
                displayUsage();
                return 0;
            case 'm':
                showManPage = true;
                break;
            case 'c':
                countOnlyNonEmptyLines = true;
                break;
            case 'v':
                enableVerboseMode = true;
                break;
            case 'l':
                limit = std::stoull(optarg);
                break;
            case 'o':
                outputFile = optarg;
                break;
        }
    }

    if (showManPage) {
        // Display manpage here
        return 0;
    }

    if (argc < 2) {
        displayUsage();
        return 1;
    }

    auto filename = argv[optind];

    std::ofstream outputStream;
    if (!outputFile.empty()) {
        outputStream.open(outputFile);
        if (!outputStream.is_open()) {
            std::cerr << "Failed to open output file: " << outputFile << "\n";
            return 1;
        }
    }

    LineCallback callback = [&](const std::string& line) {
        if (enableVerboseMode || countOnlyNonEmptyLines && !line.empty()) {
            std::cerr << "Line: " << line << "\n";
        }
        if (outputStream.is_open()) {
            outputStream << line << "\n";
        }
    };

    try {
        processLines(filename, callback, limit);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }

    if (outputStream.is_open()) {
        outputStream.close();
    }

    if (enableVerboseMode) {
        std::lock_guard<std::mutex> lock(statsMutex);
        std::cout << "Total lines: " << globalStats.lineCount << "\n";
        std::cout << "Total characters: " << globalStats.charCount << "\n";
    }

    return 0;
}
```']

