```cpp
#include <openssl/sha.h>

std::vector<char> md5(const std::string& data) {
    unsigned char digest[EVP_MD_SIZE];
    EVP_MD_CTX ctx;
    EVP_DigestInit_ex(&ctx, EVP_md5(), nullptr);
    EVP_DigestUpdate(&ctx, data.c_str(), data.size());
    EVP_DigestFinal_ex(ctx, digest, nullptr);
    std::vector<char> result(std::begin(digest), std::end(digest));
    return result;
}
```"]

