#include <sqlite3.h>

int main(void) {
  sqlite3* db;
  int rc = sqlite3_open("test.db", &db);

  if (rc != SQLITE_OK) {
    std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
    return rc;
  }

  char const *sql = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";
  sqlite3_stmt* stmt;
  rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);

  if (rc != SQLITE_OK) {
    std::cerr << "Can't prepare statement: " << sqlite3_errmsg(db) << std::endl;
    return rc;
  }

  sqlite3_bind_int(stmt, 1, /* input supervisor ID */);
  rc = sqlite3_step(stmt);

  if (rc == SQLITE_ROW) {
    const char* name = static_cast<const char*>(sqlite3_column_text(stmt, 0));
    const char* city = static_cast<const char*>(sqlite3_column_text(stmt, 1));
    const char* address = static_cast<const char*>(sqlite3_column_text(stmt, 2));

    std::cout << "Name: " << name << ", City: " << city << ", Address: " << address << std::endl;
  } else {
    std::cerr << "No matching employee found" << std::endl;
  }

  sqlite3_finalize(stmt);
  sqlite3_close(db);

  return rc;
}
```']

