namespace bs = boost::asio;

// Semaphore creation and deletion function
void createAndDeleteSemaphore(bs::io_service& io_service, int initial_value) {
    boost::mutex mtx;
    boost::condition_variable cv;
    boost::semaphore semaphore(initial_value);

    std::unique_ptr<boost::semaphore> semaPtr{std::make_unique<boost::semaphore>(semaphore)};

    auto releaseSemaphore = [&]() mutable {
        bs::post(io_service, [&]() mutable {
            std::lock_guard<boost::mutex> lock(mtx);
            semaPtr->release();
            cv.notify_one();
        });
    };

    auto waitSemaphore = [&]() mutable {
        bs::post(io_service, [&]() mutable {
            std::unique_lock<boost::mutex> lock(mtx);
            cv.wait(lock, [this]{ return semaPtr->available(); });
        });
    };

    return [semaPtr = std::move(semaPtr), releaseSemaphore = std::move(releaseSemaphore), waitSemaphore = std::move(waitSemaphore)](auto&...) -> void {
        (void)std::initializer_list<decltype(semaPtr)>{semaPtr}.begin(), std::end(std::initializer_list<decltype(semaPtr)>{semaPtr});

        for (auto&& sema : semaPtr) {
            sema->release();
        }
    };
}

// Your application logic goes here...
