    public interface IMediaStream
    {
        Task InitializeAsync(Uri url);
        ValueTask<byte[]> ReadChunkAsync();
        void Dispose();
    }

    public abstract class MediaStream : IMediaStream
    {
        protected const int BufferSize = 1024 * 64;

        private readonly Uri _url;
        private byte[] _buffer;
        private WebClient _webClient;

        protected MediaStream(Uri url)
        {
            _url = url;
            _buffer = new byte[BufferSize];
        }

        public virtual async Task InitializeAsync(Uri url)
        {
            _url = url;
            _webClient?.Dispose();
            _webClient = new WebClient();
            _webClient.DownloadDataCompleted += OnDownloadDataCompleted;
            await _webClient.DownloadDataTaskAsync(_url);
        }

        public virtual async ValueTask<byte[]> ReadChunkAsync()
        {
            return await _webClient.DownloadDataTaskAsync(0, BufferSize);
        }

        public void Dispose()
        {
            _webClient?.Dispose();
            _buffer = null;
        }

        protected virtual void OnDownloadDataCompleted(object sender, DownloadDataCompletedEventArgs e)
        {
            // Handle SSL/TLS connections, authentication, and adaptive bitrate switching here.
