2. Define the `entry` struct:

```c
typedef struct {
    uint64_t identifier;
    time_t timestamp;
    char* value;
} entry_t;
```

3. Implement a thread-safe wrapper for malloc and free functions using GSL atomic operations:

```c
void* thread_malloc(size_t size) {
    void *ptr = gsl_atomic_mlock((gsl_atom_u64*) &mem_mutex);
    ptr = malloc(size);
    if (ptr == NULL) {
        gsl_atomic_munlock((gsl_atom_u64*) &mem_mutex);
        return NULL;
    }
    gsl_atomic_munlock((gsl_atom_u64*) &mem_mutex);
    return ptr;
}

void thread_free(void *ptr) {
    if (ptr != NULL) {
        gsl_atomic_mlock((gsl_atom_u64*) &mem_mutex);
            free(ptr);
        gsl_atomic_munlock((gsl_atom_u64*) &mem_mutex);
    }
}
```

