Java (Data Processing):
```java
import com.amazonaws.services.dynamodbv2.AmazonDynamoDB;
import com.amazonaws.services.dynamodbv2.AmazonDynamoDBClientBuilder;
import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.fasterxml.jackson.databind.ObjectMapper;

public class DeviceDataProcessor implements RequestHandler<InputStream, ApiGatewayResponse> {
    private AmazonDynamoDB dynamoDb;

    public DeviceDataProcessor() {
        this.dynamoDb = AmazonDynamoDBClientBuilder.standard().build();
    }

    @Override
    public ApiGatewayResponse handleRequest(InputStream input, Context context) {
        try {
            Map<String, Object> jsonMap = new ObjectMapper().readValue(input, new TypeReference<Map<String, Object>>(){});
            storeDeviceData(jsonMap);
        } catch (IOException e) {
            return ApiGatewayResponse.builder().statusCode(500).build();
        }
        return ApiGatewayResponse.builder().statusCode(200).build();
    }

    private void storeDeviceData(Map<String, Object> data) {
        Map<String, AttributeValue> item = new HashMap<>();
        item.put("id", new AttributeValue().withS(data.get("device_id").toString()));
        item.put("data", new AttributeValue().withM(new HashMap<>()));
        for (Map.Entry<String, Object> entry : data.entrySet()) {
            ((Map<String, AttributeValue>)item.get("data")).put(entry.getKey(), new AttributeValue().withS(entry.getValue().toString()));
        }
        PutItemRequest request = new PutItemRequest()
                .withTableName("DeviceData")
                .withItem(item);
        dynamoDb.putItem(request);
    }
}
```']

