Here's a sample implementation of throttling with SlidingWindow:

```csharp
public class Throttle
{
    private readonly IDistributedCache _cache;
    private readonly TimeSpan _timeSpan;
    private readonly int _maxRequestsPerTimeSpan;

    public Throttle(IDistributedCache cache, TimeSpan timeSpan, int maxRequestsPerTimeSpan)
    {
        _cache = cache;
        _timeSpan = timeSpan;
        _maxRequestsPerTimeSpan = maxRequestsPerTimeSpan;
    }

    public bool TryAddRequest(string key)
    {
        var currentValue = _cache.GetString(key);
        int count = 0;

        if (!string.IsNullOrEmpty(currentValue))
            count = int.Parse(currentValue);

        count++;

        if (count > _maxRequestsPerTimeSpan)
            return false;

        _cache.SetString(key, count.ToString(), new DistributedCacheEntryOptions().AbsoluteExpirationRelativeToNow(_timeSpan));
        return true;
    }
}
```"]

