        .service(web::resource("/rollback").route(web::post().to(rollback_service)));

    let mut service = ServiceBuilder::new()
        .layered_on(app)
        .layer(Lazy::new(|| self_healing_service))
        .layer(RetryLayer::new())
        .layer(TimeoutLayer::new(Duration::from_secs(config.timeout)))
