    private async Task<string> GetKeyAsync(Guid keyId)
    {
        if (_redis.GetDatabase().Exists(keyId))
            return _redis.GetString(keyId);

        var token = await _userManager.GetAuthenticationTokenAsync(_userManager.Users.FirstOrDefault(u => u.Id == data.UserId), "EncryptionService1");

        var response = await _encryptionService1.PostAsJsonAsync("https://encryption-service-1.com/key", new { id = keyId, token });
