        var token = await _userManager.GetAuthenticationTokenAsync(_userManager.Users.FirstOrDefault(u => u.Id == data.UserId), "EncryptionService2");

        var response = await _encryptionService2.PostAsJsonAsync("https://encryption-service-2.com/iv", new { id = ivId, token });
