    └── compile.rs   # Rust function to measure compilation time and resident set size
```

2. **Rust Compile Function**

```rust
use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use rustc_driver::{catch_with_exit_code, RustcDriver};
use sync_tools::SyncLazy;
use log::{debug, error};

static COMPILER: SyncLazy<RustcDriver> = SyncLazy::new(|| RustcDriver::new());

fn compile() -> i32 {
    let start_time = Instant::now();
    let mut cmd = Command::new(COMPILER.get().exe().unwrap());
    cmd.stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()?;
    let resident_set_size = get_resident_set_size();

    match catch_with_exit_code(|| cmd.wait().map(|r| r.code().unwrap())) {
        Ok(code) => {
            let elapsed = start_time.elapsed().as_secs_f64();
            debug!("Compilation took {} seconds and used {}", elapsed, resident_set_size);
            code
        }
        Err(e) => {
            error!("Error while compiling: {}", e);
            early_error()
        }
    }
}
```']

