<?php
namespace App\Auth;

use Psr\Log\LoggerInterface;
use GuzzleHttp\Client as HttpClient;
use Symfony\Component\PasswordHasher\Hasher\UserPasswordHasherInterface;
use DateTimeImmutable;
use Firebase\JWT\JWT;

class Authenticator
{
    private const TOKEN_ALGORITHM = 'HS256';
    private const TOKEN_LIFETIME = 3600; // 1 hour
    private const TOKEN_ISSUER = 'your-app-name';

    private HttpClient $httpClient;
    private UserPasswordHasherInterface $passwordHasher;
    private LoggerInterface $logger;

    public function __construct(HttpClient $httpClient, UserPasswordHasherInterface $passwordHasher, LoggerInterface $logger)
    {
        $this->httpClient = $httpClient;
        $this->passwordHasher = $passwordHasher;
        $this->logger = $logger;
    }

    public function generateToken(string $userId): string
    {
        return JWT::encode([
            'sub' => $userId,
            'exp' => new DateTimeImmutable('+' . self::TOKEN_LIFETIME . ' seconds'),
        ], self::TOKEN_SECRET, self::TOKEN_ALGORITHM);
    }

    public function validateToken(string $token): bool
    {
        try {
            $decoded = JWT::decode($token, self::TOKEN_SECRET, [self::TOKEN_ALGORITHM]);
            return $decoded->exp > new DateTimeImmutable();
        } catch (\Exception $e) {
            return false;
        }
    }

    public function hashPassword(string $password): string
    {
        return $this->passwordHasher->hashPassword($this->getUser(), $password);
