#include <stdio.h>
#include <string.h>

char* appendSlashIfNecessary(char* str, size_t limit) {
    if (strlen(str) >= limit) return str;
    char* newStr = (char*) malloc(sizeof(char) * (limit + 1));
    strcpy(newStr, str);
    newStr[strlen(str)] = '/';
    free(str);
    return newStr;
}
