[' ```cpp
   #include <iostream>
   #include <thread>
   #include <mutex>
   #include <queue>
   #include <memory>
   #include <boost/asio.hpp>
   #include <kafka/client.h> // Include your Kafka client library here
   #include <tsdb_cpp/TSDBClient.h> // Include your Time-Series Database client library here

   class DataEvent {
       public:
           std::int64_t timestamp;
           std::string deviceID;
           std::string location;
           double temperature;
           double humidity;
           int batteryLevel;

           DataEvent(std::int64_t t, const std::string& d, const std::string& l, double temp, double humid, int batt)
               : timestamp(t), deviceID(d), location(l), temperature(temp), humidity(humid), batteryLevel(batt) {}
   };

   class DataProcessingEngine {
       private:
           std::queue<DataEvent> eventQueue;
           std::mutex queueMutex;
           boost::asio::io_service ioService;
           KafkaProducer kafkaProducer; // Replace with your message broker client implementation
           TSDBClient tsdbClient; // Replace with your Time-Series Database client implementation
           std::thread workerThread;
           static const int maxConcurrentWorkers = 10;
           std::vector<std::unique_ptr<Worker>> workers;

       public:
           DataProcessingEngine() {
               for (int i = 0; i < maxConcurrentWorkers; ++i) {
                   workers.emplace_back(std::make_unique<Worker>(ioService, queueMutex, kafkaProducer, tsdbClient));
               }
               workerThread = std::thread(&DataProcessingEngine::run, this);
           }

           ~DataProcessingEngine() {
               workerThread.join();
           }

           void enqueueEvent(const DataEvent& event) {
               std::lock_guard<std::mutex> lock(queueMutex);
               eventQueue.push(event);
               ioService.post([this]() { notifyWorker(); });
           }

           void notifyWorker() {
               for (auto& worker : workers) {
                   worker->notify();
               }
           }

           void run() {
               while (true) {
                   std::unique_lock<std::mutex> lock(queueMutex);
                   eventQueue.wait_and_pop(lock);
                   processEvent(eventQueue.front());
               }
           }

           void processEvent(const DataEvent& event) {
               // Implement processing logic here, e.g., persist data to the Time-Series Database
           }
   };

   class Worker {
       private:
           boost::asio::io_service& ioService;
           std::mutex* queueMutex;
           KafkaProducer& kafkaProducer;
           TSDBClient& tsdbClient;

       public:
           Worker(boost::asio::io_service& ios, std::mutex* qm, KafkaProducer& p, TSDBClient& c)
               : ioService(ios), queueMutex(qm), kafkaProducer(p), tsdbClient(c) {}

           void notify() {
               ioService.post([this]() { processQueue(); });
           }

           void processQueue() {
               std::unique_lock<std::mutex> lock(*queueMutex);
               if (eventQueue.empty()) return;

               DataEvent event = eventQueue.front();
               eventQueue.pop();
               processEvent(event);
           }

           void processEvent(const DataEvent& event) {
               // Implement processing logic here, e.g., publish data to the message broker and persist to the Time-Series Database
           }
   };
   ```']

