import axios from 'axios';
import geolocationService from './geolocationService';
import themeManager from './themeManager';
import log from './log';
import config from '../config';

const Notification = {
  text: '',
  imageUrl: '',
  mediaUrl: '',
  buttons: [],
  deeplink: '',
  priority: 'normal',
  geolocation: null,
  theme: themeManager.getCurrentTheme(),
};

class NotificationService {
  constructor(user) {
    this.user = user;
    this._queue = [];
  }

  async sendUserNotifications() {
    if (!this.user.connected) {
      this._queue.push(Notification);
      return;
    }

    try {
      const notificationsToSend = this._queue.sort((a, b) => {
        if (a.priority === 'urgent' && b.priority !== 'urgent') return -1;
        if (a.priority !== 'urgent' && b.priority === 'urgent') return 1;
        return a.timestamp - b.timestamp;
      });

      for (const notification of notificationsToSend) {
        const geolocation = await geolocationService.getGeolocation();
        notification.geolocation = geolocation;

        try {
          const response = await axios.post(
            `${config.NOTIFICATION_API_URL}/${this.user.platform}`,
            notification,
            {
              headers: {
                Authorization: `Bearer ${this.user.accessToken}`,
              },
            }
          );

          log.info(`Sent notification to user: ${JSON.stringify(notification)}`);
        } catch (error) {
          const isTransientError = error.response && error.response.status === 503;
          if (!isTransientError) {
            log.error(`Failed to send notification: ${error}`);
          } else {
            // Backoff logic goes here
          }
        }
      }
    } catch (error) {
      log.error(`Failed to process user notifications: ${error}`);
    }
  }
}
```

