['Here is a basic structure for your Java service. I've used Apache Commons VFS (File System Abstraction Library) for handling various storage systems, OkHttp for network communication, Bouncy Castle for SHA-256 computations and Jackson for JSON serialization/deserialization.

```java
import com.google.common.hash.HmacSha256;
import com.google.common.io.Files;
import okhttp3.*;
import org.apache.commons.vfs2.*;
import org.bouncycastle.util.IOUtils;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class HashService {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private final FileSystemManager vfsManager;
    private final OkHttpClient httpClient;

    public HashService(FileSystemManager vfsManager, OkHttpClient httpClient) {
        this.vfsManager = vfsManager;
        this.httpClient = httpClient;
    }

    public String computeHash(String fileUri) throws IOException, GeneralSecurityException {
        FileFileSystemResource resource = new FileFileSystemResource(fileUri);
        InputStream in = resource.getInputStream();
        byte[] hashBytes = HmacSha256.newHmacSha256Builder().key("yourSecretKey").thenRehashed(256).hashByteArray(IOUtils.toByteArray(in));
        return hexadecimalString(hashBytes);
    }

    public String verifyHash(String fileUri, String hash) throws IOException, GeneralSecurityException {
        FileFileSystemResource resource = new FileFileSystemResource(fileUri);
        InputStream in = resource.getInputStream();
        byte[] hashBytes = IOUtils.toByteArray(in);
        HmacSha256 hmac = HmacSha256.newHmacSha256Builder().key("yourSecretKey").thenRehashed(256).hashByteArray(hashBytes);
        byte[] expectedHashBytes = hmac.asBytes();
        return hexadecimalString(expectedHashBytes).equals(hash) ? "Valid" : "Invalid";
    }

    public Response computeAndVerifyHashAsync(Request request) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<String> hashFuture = executor.submit(() -> computeHash(request.getFileUri()));
        Future<String> verifyFuture = executor.submit(() -> verifyHash(request.getFileUri(), request.getHash()));
        try {
            String hash = hashFuture.get();
            String verificationResult = verifyFuture.get();
            // return a custom response object containing hash and verification result
        } catch (ExecutionException e) {
            // handle exceptions from the futures, e.g. by returning an error response
        } finally {
            executor.shutdown();
        }
    }

    private String hexadecimalString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

For error handling, you can check the status code of the OkHttpResponse and deserialize error responses to handle specific errors like network failures, authentication issues, and file access permissions.

