class CircuitBreakerApi:
    def __init__(self, api):
        self.api = api
        self.status = 'closed'
        self.timeout = 60
        self.failure_ratio = 0.5
        self.reset_time = self.timeout

    async def call(self, *args, **kwargs):
        if self.status == 'open':
            await asyncio.sleep(self.reset_time)
            self.status = 'closed'
            self.reset_time = self.timeout
            return await self.api(*args, **kwargs)
        elif self.failure_ratio > 0.5:
            self.status = 'open'
            self.reset_time /= 2
        else:
            self.failure_ratio += (1 - self.failure_ratio) * ((self.api(*args, **kwargs).exception != None) and 1 or 0)
        return await self.call(*args, **kwargs)

