use std::fs::{self, File};
use std::io::{self, Write};
use std::os::unix::prelude::CmdExt;
use std::process::Command;
use std::time::Instant;
use sync_runtime::SyncLazy;

static LOGGER: SyncLazy<Box<dyn FnMut(&str) + Send + Sync> = SyncLazy::new(|| {
    let logger = Box::new(|msg| println!("{}", msg));
    // Initialize log hook here
    logger
});

fn compile_rust() -> io::Result<i32> {
    let start = Instant::now();
    let mut command = Command::new("rustc");
    let args = env::args().skip(1);
    command.args(&args);

    // Install ice hook and catch any errors
    command.arg("--emit=event=ice")
        .arg("-C")
        .arg("debuginfo=2")
        .arg("-C")
        .arg("opt-level=3")
        .arg("-C")
        .arg("lto")
        .arg("-C")
        .arg("use-native-threads")
        .arg("-C")
        .arg("no-canvey")
        .stdin(io::Stdio::null())
        .stdout(io::Stdio::piped())
        .stderr(io::Stdio::piped())
        .spawn()?;
    let mut child = command.into_child()?;
    let stdout = child.stdout?.take();
    let mut stderr = child.stderr?.take();

    let resident_set_size_before = get_resident_set_size();

    // Use the `SyncLazy` logger with a custom error handler
    let log_hook = LOGGER.with(|logger| Box::new(move |msg| {
        let _ = logger(msg);
        io::stdout().flush()?;
    }));
    let mut logger = log_hook.clone();

    rustc_driver::catch_with_exit_code(move || {
        for line in stdout.lines() {
            if let Ok(line) = line {
                if !line.is_empty() {
                    logger(&line);
                }
            }
        }
        child.wait()?;
        let resident_set_size_after = get_resident_set_size();
        Ok(())
    }, |e| {
        early_error(format!("Compilation failed: {}", e));
        Err(e)
    })?;

    let resident_set_size_delta = resident_set_size_after - resident_set_size_before;
    println!(
        "Compilation took {} seconds and increased memory usage by {}",
        start.elapsed().as_secs_f64(),
        resident_set_size_delta
    );
    Ok(0)
}

fn get_resident_set_size() -> i32 {
    // Implement memory usage measurement code here
    0
}

fn early_error(msg: String) {
