    public class DynamicQueryService
    {
        private readonly IDictionary<string, string> _supportedDatabases;
        private readonly IConnectionMultiplexer _redis;
        private readonly ILogger<DynamicQueryService> _logger;
        private const int MaxRetries = 5;
        private const int TimeoutInSeconds = 10;

        public DynamicQueryService(IConfiguration configuration, ILogger<DynamicQueryService> logger)
        {
            _supportedDatabases = configuration.GetSection("SupportedDatabases").AsEnumerable().ToDictionary(x => x.Key, x => x.Value);
            _redis = ConnectionMultiplexer.Connect(_configuration["Redis:ConnectionString"]);
            _logger = logger;
        }

        public async Task<DataTableReader> ExecuteDynamicQuery(byte[] queryBytes, string connectionString, IDictionary<string, object> parameters)
        {
            var dbName = GetDatabaseFromConnectionString(connectionString);
            if (!_supportedDatabases.ContainsKey(dbName))
            {
                throw new ArgumentException($"The provided connection string is not supported: {connectionString}");
            }

            var queryText = DecodeAndSanitizeQuery(queryBytes);
            var cacheKey = CreateCacheKey(dbName, queryText);

            var redisDb = _redis.GetDatabase();

            object result;
            bool isFromCache;

            lock (redisDb)
            {
                if (redisDb.Exists(cacheKey))
                {
                    isFromCache = true;
                    result = redisDb.StringGet(cacheKey);
                }
                else
                {
                    isFromCache = false;
                    result = await ExecuteQueryInternallyAsync(connectionString, queryText, parameters).ConfigureAwait(false);
                    if (result != null)
                    {
                        redisDb.StringSet(cacheKey, JsonConvert.SerializeObject(result), TimeSpan.FromSeconds(TimeoutInSeconds));
                    }
                }
            }

            if (result is DataTableReader dataTableReader)
            {
                return dataTableReader;
            }

            throw new InvalidOperationException("Unexpected result type from the query execution.");
        }

        private string GetDatabaseFromConnectionString(string connectionString)
        {
            // Implement parsing logic to extract database name from connection string
        }

        private static string DecodeAndSanitizeQuery(byte[] queryBytes)
        {
            var decodedQuery = Encoding.UTF8.GetString(queryBytes);
            return SanitizeSqlInjection(decodedQuery);
        }

        private static string SanitizeSqlInjection(string input)
        {
            // Implement SQL sanitization logic using a library or custom function
        }

        private static string CreateCacheKey(string dbName, string queryText)
        {
            return $"{dbName}:{queryText}";
        }

        private async Task<object> ExecuteQueryInternallyAsync(string connectionString, string queryText, IDictionary<string, object> parameters)
        {
            var dbProviderFactory = DbProviderFactories.GetFactory(connectionString);
            using (var connection = dbProviderFactory.CreateConnection())
            {
                await RetryAsync(async () =>
                {
                    try
                    {
                        await connection.OpenAsync().ConfigureAwait(false);
                        using (var command = new DbCommand(queryText, connection))
                        {
                            foreach (var parameter in parameters)
                            {
                                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                            }

                            var dataTableReader = await command.ExecuteReaderAsync().ConfigureAwait(false);
                            return dataTableReader;
                        }
                    }
                    catch (Exception ex) when (ex is SqlException || ex is TimeoutException)
                    {
                        _logger.LogError(ex, "An error occurred while executing the query.");
                    }
                }, MaxRetries).ConfigureAwait(false);
            }
        }

        private async Task<TResult> RetryAsync<TResult>(Func<Task<TResult>> action, int maxRetries = 5)
