#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <cryptography/rsa.h>
#include <logging_framework.h>
#include <data_service.h>
#include <cloud_monitoring.h>
#include <cache.h>
#include <checksum.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

void *process_file(void *arg);

void InfrastructureConfigurator(int argc, char **argv) {
    if (parse_command_line(argc, argv)) {
        return;
    }

    init_logging();
    init_data_service();
    init_cloud_monitoring();

    pthread_t threads[MAX_THREADS];
    FILE **files = load_input_files();
    NFAPI_CRC_INDICATION_PDU_T *results = malloc(MAX_DATA_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int thread_index = 0;

    for (int i = 0; i < MAX_INPUT_FILES; ++i) {
        if (!files[i]) {
            break;
        }

        pthread_create(&threads[thread_index], NULL, process_file, &files[i]);
        thread_index++;
    }

    for (int i = 0; i < thread_index; ++i) {
        pthread_join(threads[i], NULL);
    }

    save_results(results);
    free(results);
    free_input_files(files);

    deinit_data_service();
    deinit_cloud_monitoring();
    deinit_logging();
}

void *process_file(void *arg) {
    FILE *file = (FILE *)arg;

    if (!file) {
        log_error("Invalid file handle");
        return NULL;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat)) {
        log_error("Error getting file status");
        fclose(file);
        return NULL;
    }

    if (file_stat.st_size > MAX_FILE_SIZE) {
        log_error("File exceeds max size limit");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    while (!feof(file) && !ferror(file)) {
        if (parse_data(file, pdu)) {
            log_error("Error parsing data");
            fclose(file);
            free(pdu);
            return NULL;
        }

        set_random_crcflag(pdu->CRC_INDICATION.CRCFLAG);

        cache_insert(pdu, RX_UE_INFORMATION_TAG, pdu->RX_UE_INFORMATION_TAG);
        results[get_cache_index()] = *pdu;
    }

    fclose(file);
    free(pdu);
    return NULL;
}
```

