fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} FILE PATH_TO_GRAMMAR", args[0]);
        return;
    }

    let file_path = &args[1];
    let grammar_path = &args[2];

    // Initialize config, logger, and distributed tracing system.
    let config = Config::new(file_path, grammar_path);
    let (sender, receiver) = channel::<Result<(), Error>>();

    // Start parallel processing threads with custom thread pool.
    let mut threads = vec![];
    for _ in 0..num_cpus::get() {
        let (tx, rx) = channel::<(String, Vec<u8>)>();
        let receiver_clone = receiver.clone();
        let sender_clone = sender.clone();
        threads.push(thread::spawn(move || {
            loop {
                match tx.recv() {
                    Ok((file, data)) => {
                        let result = process_file(config.clone(), file, data);
                        sender_clone.send(result).unwrap();
                    }
                    Err(_) => break, // Thread exits when channel is dropped or error occurs.
                }
            }
        }));
    }

    let files = util::read_files_from_dir(file_path)?;
    for (i, file) in files.iter().enumerate() {
        threads[i % num_cpus::get()]
            .send((file.clone(), read_file(file)?))
            .unwrap();
    }

    let mut errors = vec![];
    while let Ok(result) = receiver.recv() {
        match result {
            Ok(_) => (), // Ignore successful results.
            Err(e) => errors.push(e),
        }
    }

    if !errors.is_empty() {
        for e in &errors {
            eprintln!("Error: {}", e);
        }
        return;
    }
}
```

