```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

int convert_image(const char *input, const char *output) {
    pid_t child = fork();

    if (child == -1) {
        perror("fork failed");
        return 1;
    } else if (child == 0) { // child process
        execlp("convert", "convert", input, output, NULL);
        perror("execlp failed");
        exit(1);
    } else { // parent process
        int status;
        waitpid(child, &status, 0);
        return WEXITSTATUS(status);
    }
}
```

Note that this function does not handle errors from the `convert` command gracefully, as per your request. You may wish to implement additional error checking and handling in a more robust manner suitable for production use.']

