using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Data;

public class ResourceManager
{
    private readonly ConcurrentDictionary<string, Task<DataTableReader>> _resourceCache = new ConcurrentDictionary<string, Task<DataTableReader>>();
    private readonly HttpClient _httpClient;
    private const int MaxRetries = 3;
    private const TimeSpan BackoffMultiplier = TimeSpan.FromMilliseconds(200);

    public ResourceManager()
    {
        _httpClient = new HttpClient();
    }

    public async Task<DataTableReader> LoadResourceAsync(byte[] data)
    {
        var resourceKey = Convert.ToBase64String(data);
        if (_resourceCache.TryGetValue(resourceKey, out var cachedTask))
            return await cachedTask;

        var requestMessage = new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            Content = new ByteArrayContent(data)
        };

        for (var retryCount = 0; ; retryCount++)
        {
            try
            {
                var response = await _httpClient.SendAsync(requestMessage);
                if (!response.IsSuccessStatusCode)
                    continue;

                using var stream = await response.Content.ReadAsStreamAsync();
                return await LoadDataTableReaderAsync(stream);
            }
            catch (Exception ex)
            {
                if (retryCount >= MaxRetries)
                    throw new Exception("Maximum retries reached", ex);
                await Task.Delay((int)(BackoffMultiplier.TotalMilliseconds * Math.Pow(2, retryCount)), CancellationToken.None);
            }
        }
    }

    private async Task<DataTableReader> LoadDataTableReaderAsync(Stream stream)
    {
