For a given command `command`, the function to execute it in the background could look like this:

```c
int run_command(const char *command) {
    pid_t child_pid;
    int status;

    // Encrypt sensitive parameters here before passing them to the child process
    char *args[] = {"sh", "-c", command, NULL};
    if ((child_pid = fork()) < 0) {
        return 0;
    } else if (child_pid == 0) {
        // Child process: execute the command and exit
        execvp(args[0], args);
        perror("execvp failed");
        _exit(1);
    } else {
        // Parent process: wait for child to finish and check its exit status
        if (waitpid(child_pid, &status, 0) < 0) {
            return 0;
        }
        return WIFEXITED(status) ? WEXITSTATUS(status) : 1;
    }
}
