    return event_type_strings[type];
}

enum EventType network_event_string_to_type(const char* str) {
    for (size_t i = 0; i < sizeof(event_type_strings) / sizeof(char*); ++i) {
        if (strcmp(str, event_type_strings[i]) == 0) return i;
    }
    return UNKNOWN;
}
