**dynamic_array.c**
```cpp
#include "dynamic_array.h"
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

void dynamic_array_init(DynamicArray* array) {
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

DynamicArray* dynamic_array_new(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    dynamic_array_init(array);
    dynamic_array_resize(array, initial_capacity);

    return array;
}

void dynamic_array_free(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i)
        network_event_free(array->data[i]);

    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

NetworkEvent** dynamic_array_get_data(const DynamicArray* array) {
    return array->data;
}

size_t dynamic_array_get_size(const DynamicArray* array) {
    return array->size;
}

void dynamic_array_push_back(DynamicArray* array, NetworkEvent* event) {
    pthread_mutex_lock(&array->mutex);

    if (array->capacity == array->size) {
        array->capacity *= 2;
        array->data = realloc(array->data, sizeof(NetworkEvent*) * array->capacity);
        if (!array->data) {
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }

    array->data[array->size] = event;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

NetworkEvent* dynamic_array_at(const DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);

    NetworkEvent* event = array->data[index];
    pthread_mutex_unlock(&array->mutex);

    return event;
}

void dynamic_array_resize(DynamicArray* array, size_t new_capacity) {
    if (new_capacity <= array->size) return;

    NetworkEvent** tmp = realloc(array->data, sizeof(NetworkEvent*) * new_capacity);
    if (!tmp) return;

    memset(&tmp[array->size], 0, sizeof(NetworkEvent*) * (new_capacity - array->size));
    array->data = tmp;
    array->capacity = new_capacity;
}

void dynamic_array_sort(DynamicArray* array, int (*compar)(const void*, const void*)) {
    qsort(array->data, array->size, sizeof(NetworkEvent*), compar);
}

bool dynamic_array_filter(DynamicArray* array, bool (*predicate)(NetworkEvent* event)) {
    size_t new_size = 0;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (predicate(array->data[i])) {
            if (new_size >= array->capacity) {
                array->capacity *= 2;
                array->data = realloc(array->data, sizeof(NetworkEvent*) * array->capacity);
                if (!array->data) break;
            }
            array->data[new_size] = array->data[i];
            new_size++;
        }
    }

    array->size = new_size;
    pthread_mutex_unlock(&array->mutex);

    return true;
}
```

