DynamicArray* loader_init(const char* filename, Parser parser) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    DynamicArray* array = dynamic_array_new(8);
    if (!array) {
        fclose(file);
        return NULL;
    }

    NetworkEvent* event = NULL;
    size_t event_count = 0;

    while (parser(fgets(NULL, sizeof(char), file), &event, &event_count)) {
        dynamic_array_push_back(array, network_event_new(time(NULL), UNKNOWN, event_count));
    }

    fclose(file);
    return array;
}

void loader_free(DynamicArray* array) {
    dynamic_array_free(array);
}
