        res = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        if (res != CURLE_OK) {
            bslg::error("Failed to set HTTP header: {}", curl_easy_strerror(res));
            return;
        }

        std::unique_ptr<char[], decltype(&curl_free)> buffer(static_cast<char*>(malloc(CHUNK_SIZE)), &curl_free);
        size_t written = 0;
        res = curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void *ptr, size_t size, size_t nmemb, void *userp) {
            static_cast<std::unique_ptr<char[], decltype(&curl_free)>*>(userp)->append((size_t)(size * nmemb), static_cast<const char*>(ptr));
            return static_cast<size_t>(size * nmemb);
        });
        if (res != CURLE_OK) {
            bslg::error("Failed to set write function: {}", curl_easy_strerror(res));
            return;
        }
        res = curl_easy_setopt(curl, CURLOPT_WRITEDATA, buffer.get());
        if (res != CURLE_OK) {
            bslg::error("Failed to set write data: {}", curl_easy_strerror(res));
            return;
        }

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &written);
            if (written >= 400 && written < 600) {
                bslg::error("HTTP request failed with status code {}", static_cast<int>(written));
            } else {
                curl_easy_getinfo(curl, CURLINFO_ERRORCODE, error_buffer);
                bslg::error("cURL error: {}", error_buffer);
            }
        } else {
            Json::CharReaderBuilder builder;
            Json::CharReader *reader = builder.newCharReader();
            std::string contents(buffer->get(), buffer->size());
            JSONCPP_STRING errs;
            bool parsingSuccessful = reader->parse(contents, &errs);
            delete reader;

            if (!parsingSuccessful) {
                bslg::error("Failed to parse JSON response: {}", errs.c_str());
                return;
            }

            Json::Value root;
            Json::Reader reader2;
            bool success = reader2.parse(contents, root);
            if (success) {
                for (const auto &value : root) {
                    int num = value.asInt();
                    std::lock_guard<std::mutex> lock(mtx);
                    integers.push_back(num);
                    largest = std::max(largest, num);
                }
            } else {
                bslg::error("Failed to parse JSON response: {}", errs.c_str());
                return;
            }
        }

        curl_easy_cleanup(curl);
    }

    void retry() {
        std::unique_ptr<std::thread, decltype(&curl_global_cleanup)> thread_cleanup(new std::thread([this]() { this->fetch(); }), &curl_global_cleanup);
        if (!running) {
            bslg::debug("Retrying fetch with exponential backoff");
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * std::pow(2, thread_count++)));
        }
    }

    void stop() {
        running = false;
    }

private:
    static std::atomic<int> thread_count{0};
};

class DataStore {
public:
    DataStore(size_t num_threads) : fetchers_(num_threads), log_file_("data.log") {}

    void start() {
        for (auto &fetcher : fetchers_) {
            fetcher.start();
        }

        asio::io_service io_service;
        signal(SIGINT, [](int) {
            bslg::info("Exiting...");
            stopAllFetches();
            io_service.stop();
        });

        io_service.run();
    }

    int getLargest() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return largest_;
    }

private:
    void stopAllFetches() {
        for (auto &fetcher : fetchers_) {
            fetcher.stop();
        }
    }

    std::vector<DataFetcher> fetchers_;
    mutable std::mutex mutex_;
    int largest_ = INT_MIN;
    fs::path log_file_;
};

void createLogDirectory() {
    if (!fs::exists("logs")) {
        fs::create_directory("logs");
    }
}

int main(int argc, char *argv[]) {
    try {
        createLogDirectory();
        DataStore store(4);
        store.start();

        // RESTful API endpoint for querying the largest integer
