['1. C Function for Random Array Initialization:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} record;

void initArray(record** array, int size, int minVal, int maxVal) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i] = malloc(sizeof(record));
        array[i]->key = i;
        array[i]->offset = rand() % 1000000000 + 1;
        array[i]->value = rand() % (maxVal - minVal + 1) + minVal;
    }
}
```

2. Multi-Threaded C# Service:

This code demonstrates a simplified version of the multi-threaded service using .NET Core and Redis as a cache. Adjustments may be needed to fully implement the requirements, such as error handling, logging, and scaling mechanisms.

```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using Newtonsoft.Json;
using StackExchange.Redis;

public class ConfigurationService
{
    private readonly IConnectionMultiplexer _redis;
    private readonly ConcurrentDictionary<string, dynamic> _configCache = new ConcurrentDictionary<string, dynamic>();
    private readonly HttpClient _httpClient;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(5);

    public ConfigurationService()
    {
        _redis = ConnectionMultiplexer.Connect("localhost");
        _httpClient = new HttpClient();
    }

    private dynamic GetConfigFromCache(string key)
    {
        return _configCache.GetOrAdd(key, (k) =>
        {
            var redisDb = _redis.GetDatabase();
            if (redisDb.Exists(key))
                return JsonConvert.DeserializeObject(redisDb.StringGet(key));
            else
                return GetConfigFromAPI(key);
        });
    }

    private dynamic GetConfigFromAPI(string key)
    {
        try
        {
            var response = _httpClient.GetAsync($"https://config-api-endpoint/{key}").Result;
            if (response.IsSuccessStatusCode)
            {
                var content = response.Content.ReadAsStringAsync().Result;
                var config = JsonConvert.DeserializeObject(content);

                // Store the configuration in Redis with a TTL to ensure freshness.
                _redis.GetDatabase().KeyDelete(key);
                _redis.GetDatabase().StringSetEx(key, JsonConvert.SerializeObject(config), TimeSpan.FromHours(1));

                return config;
            }
        }
        catch (Exception ex)
        {
            // Log the error and retry after a specified interval.
            Console.WriteLine($"Error fetching configuration from API: {ex.Message}");
            Task.Delay(_retryInterval).ContinueWith(task => GetConfigFromAPI(key));
        }

        return null;
    }
}
```

This C# service uses a Redis database for caching and handling concurrent updates, implementing a basic retry mechanism when fetching configuration data from the API. To fully implement the requirements as stated, additional work would be needed to address error handling, logging, load balancing, auto-scaling, and more robust connection retries. Additionally, you can utilize dependency injection for better modularity and easier updates/enhancements.']

