3. C# function for decrypting a Base64-encoded, encrypted message using Triple DES encryption:

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace EncryptionUtil
{
    public class EncryptionHelper
    {
        private const string IV = "0123456789abcdef";
        private static readonly TripleDESCryptoServiceProvider _desCryptoProvider = new TripleDESCryptoServiceProvider();

        public async Task<string> DecryptBase64EncryptedMessageAsync(string base64EncryptedData, string key)
        {
            byte[] encryptedDataBytes = Convert.FromBase64String(base64EncryptedData);
            byte[] ivBytes = Encoding.ASCII.GetBytes(IV);

            _desCryptoProvider.Key = Encoding.UTF8.GetBytes(key);

            ICryptoTransform cryptoTransform = _desCryptoProvider.CreateDecryptor(ivBytes, _desCryptoProvider.CreateInitVector(ivBytes));
            byte[] decryptedDataBytes = cryptoTransform.TransformFinalBlock(encryptedDataBytes, 0, encryptedDataBytes.Length);

            return Encoding.UTF8.GetString(decryptedDataBytes);
        }
    }
}
```']

