Backend Service (Node.js/Express.js):

```javascript
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const passport = require('passport');
const session = require('express-session');

const app = express();
app.use(cors());
app.use(session({ secret: 'secret_key' }));
app.use(passport.initialize());
app.use(passport.session());

// Protect routes with authentication middleware
function authenticate(req, res, next) {
  passport.authenticate('jwt', { session: false }, (err, user, info) => {
    if (err || !user) {
      return res.status(401).send({ error: 'Unauthorized' });
    }
    req.user = user;
    next();
  })(req, res, next);
}

// Example route using JWT authentication
app.get('/example', authenticate, (req, res) => {
  // Handle request here
});
```

Messaging System:

```javascript
const amqp = require('amqplib/callback_api');

async function sendMessage(queue, message) {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  channel.assertQueue(queue);
  channel.sendToQueue(queue, Buffer.from(JSON.stringify(message)));
  console.log(`[x] Sent ${JSON.stringify(message)}`);

  channel.close();
  connection.close();
}
```

Microservices Architecture is beyond the scope of a single code snippet but you can refer to resources like [Microservice Patterns](https://microservices.io/) and [Microservices Design Patterns](https://martinfowler.com/articles/microservices.html) for further guidance on implementing microservices architecture.

