2. **Memory Manager**: Implement a thread-safe memory manager to handle dynamic resizing of arrays, using `std::vector` for each data structure (offsets, keys, CellularSession records).

```cpp
#include <mutex>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <vector>

template<typename T>
class ConcurrentArray {
public:
    explicit ConcurrentArray(size_t initialSize, size_t maxSize)
        : data_(initialSize), mutex_(), notifier_(), size_(initialSize), maxSize_(maxSize) {}

    void Resize(size_t newSize) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (newSize > maxSize_) {
            notifier_.wait(lock);
        }
        if (newSize < size_) {
            data_.erase(data_.end() - size_, data_.end());
            size_ = newSize;
        } else {
            for (size_t i = size_; i < newSize; ++i) {
                data_.push_back(T());
            }
            size_ = newSize;
        }
    }

private:
    std::vector<T> data_;
    std::mutex mutex_;
    std::condition_variable notifier_;
    std::atomic<size_t> size_;
    const size_t maxSize_;
};
```

