Asynchronous reduce function in JavaScript:

```javascript
function asyncReduce(arr, initialValue, callback) {
    return new Promise((resolve, reject) => {
        let result = initialValue;
        let index = 0;

        function next() {
            if (index >= arr.length) {
                resolve(result);
            } else {
                callback(result, arr[index], () => {
                    result = arguments[0];
                    index++;
                    next();
                });
            }
        }

        next();
    });
}
```']

