['1. **Custom Memory Allocator**

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct CellularSession {
    char imei[15];
    int serving_cell_id;
    // QoS flows list, DSCP values, etc.
} CellularSession;

typedef struct ObjectPool {
    CellularSession *slabs[SLAB_COUNT];
    size_t num_free;
    pthread_mutex_t lock;
} ObjectPool;

void init_pool(ObjectPool *pool, size_t slab_count) {
    // Initialize pool structure and slabs
}

CellularSession* alloc_cellular_session(ObjectPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->num_free > 0) {
        CellularSession *cs = pool->slabs[0][--pool->num_free];
        memset(cs, 0, sizeof(CellularSession));
        pthread_mutex_unlock(&pool->lock);
        return cs;
    }
    // Create a new CellularSession object and add it to the first slab
    pthread_mutex_unlock(&pool->lock);
    // Return a newly created CellularSession
}

void free_cellular_session(CellularSession *cs, ObjectPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->num_free < SLAB_COUNT) {
        pool->slabs[0][pool->num_free] = cs;
        ++pool->num_free;
    } else {
        // Handle memory exhaustion scenario, for example: expand a different slab or use a different allocator.
    }
    pthread_mutex_unlock(&pool->lock);
}
```

