struct MaxHeapNode {
    int data;
    int rank;
    struct MaxHeapNode *parent;
};

void swap(struct MaxHeapNode *a, struct MaxHeapNode *b) {
    struct MaxHeapNode temp = *a;
    *a = *b;
    *b = temp;
}

int get_left_child_index(int parent_index) {
    return (2 * parent_index) + 1;
}

int get_right_child_index(int parent_index) {
    return (2 * parent_index) + 2;
}

void increase_rank(struct MaxHeapNode* x) {
    x->rank++;
    while (x->parent && (x->parent->rank < x->rank)) {
        swap(x, x->parent);
        x = x->parent;
    }
}

