    private function loadConcurrently($resourceDataArray) {
        $tasks = array_map([$this, 'createTask'], $resourceDataArray);
        array_walk($tasks, [$this, 'submitToCache']);
        foreach ($tasks as $task) {
            $task->run();
        }

        return array_column($this->cache->getMatchingDelegates(__TOSTRING__), 'getData');
    }

    private function createTask($resourceData) {
        return new ResourceLoaderTask($resourceData, $this->config);
    }

    private function submitToCache(ResourceLoaderTask $task) {
        if (!$this->cache->contains($task)) {
            $this->cache[$task] = function () use ($task) {
                return $task->load();
            };
        }
    }

    private function getDataFromCache(ResourceLoaderTask $task) {
        return $this->cache->get($task)->__invoke();
    }

    private function generateScriptTags(array $resources) {
        foreach ($resources as $resource) {
            $key = uniqid();
            $scriptContent = htmlspecialchars($resource->getContent());
            $this->scriptTags[] = "<script id='{$key}'>{$scriptContent}</script>";
        }
    }

    private function getFooter() {
        return implode("\n", $this->scriptTags);
    }
}

