    void initializeSecurityLibrary() {
        // Initialize OpenSSL
        EVP_ssl_init();

        // Set retry mechanism for API calls with exponential backoff
        static constexpr size_t MAX_RETRIES = 5;
        static constexpr double BACKOFF_FACTOR = 2.0;
        static std::atomic<size_t> currentRetry{0};

        auto apiCall = [&](const std::string& url) {
            CURL* curl;
            CURLcode res;

            // Initialize the cURL session with custom settings
            curl_global_init(CURL_GLOBAL_DEFAULT);
            curl = curl_easy_init();
            if (!curl) throw std::runtime_error("Failed to initialize cURL.");

            // Make API call and handle responses or errors
            res = curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            if (res != CURLE_OK) throw std::runtime_error(curl_easy_strerror(res));
            res = curl_easy_perform(curl);

            // Cleanup cURL resources
            if (res == CURLE_OK) {
                auto responseCode = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
                if (responseCode != 200) throw std::runtime_error("API call failed with status code " + std::to_string(responseCode));
            } else {
                if (currentRetry < MAX_RETRIES) {
                    double delay = std::pow(BACKOFF_FACTOR, currentRetry);
                    std::this_thread::sleep_for(std::chrono::milliseconds(delay * 1000));
                    ++currentRetry;
                    apiCall(url);
                } else {
                    throw std::runtime_error("Failed to contact the API after multiple retries.");
                }
            }

            curl_easy_cleanup(curl);
        };

        // Fetch keys and policies from the API
