use futures::stream::StreamExt;

// Define the LogEntry struct
#[derive(Serialize, Deserialize)]
struct LogEntry {
    timestamp: String,
    severity: String,
    message: String,
    metadata: Value,
}

// Define the PriorityQueue struct with thread-safe access
struct PriorityQueue {
    inner: VecDeque<LogEntry>,
    priority_map: HashMap<String, u32>,
}

impl PriorityQueue {
    fn new() -> Self {
        let mut priority_map = HashMap::new();
        priority_map.insert("ERROR".to_string(), 1);
        priority_map.insert("WARNING".to_string(), 2);
        priority_map.insert("INFO".to_string(), 3);
        Self {
            inner: VecDeque::new(),
            priority_map,
        }
    }

    fn push(&mut self, log_entry: LogEntry) {
        let priority = self.priority_map.get(&log_entry.severity).unwrap_or(&&3);
        self.inner.push_back((*priority as u64, log_entry));
        self.inner.sort_unstable_by(|a, b| a.0.cmp(&b.0));
    }

    async fn pop(&mut self) -> Option<LogEntry> {
        self.inner.pop_front().map(|(_, log_entry)| log_entry)
    }
}

