        App::new().route("/health", web::get().to(|| async move { HttpResponse::Ok().body("ok") }))
            .route("/ws", web::websocket().to(|r| {
                let buffer = r.data::<Arc<RwLock<PriorityQueue>>>();
                let oauth_handler = r.app_data::<OAuthHandler>();

