                                Err(_) => break,
                            }
                        }

                        oauth_guard
                    });
                };

                web::WebsocketHandler::new(handler)
            }))
            .default_service(|r| {
                r.response(HttpResponse::NotFound().body("404 Not Found"))
            })
            .bind("127.0.0.1:8080")
            .workers(4)
            .run()
            .await
    });
