```java
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.time.Instant;

public class DisjointPairs {
    private UnionFind uf;

    public DisjointPairs(int[] arr) {
        uf = new UnionFind(arr.length);
        for (int i = 0; i < arr.length; i++)
            uf.union(i, arr[i]);
    }

    public int numDisjointPairs() {
        return uf.getSize();
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int x) {
            if (x != parent[x])
                parent[x] = find(parent[x]);
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY)
                return;
            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

        public int getSize() {
            int totalSize = 0;
            for (int i = 0; i < parent.length; i++) {
                totalSize += size[parent[i]];
            }
            return totalSize;
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5};
        DisjointPairs dp = new DisjointPairs(arr);
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                int pair = arr[i] * arr[j];
                System.out.println(String.format("Pair (%d, %d) is disjoint in %d ms", arr[i], arr[j], dp.findPairDisjointTime(i, j)));
            }
        }
    }

    private long findPairDisjointTime(int i, int j) {
        long start = Instant.now().toEpochMilli();
        if (uf.find(i) != uf.find(j)) {
            uf.union(i, j);
        }
        return Instant.now().toEpochMilli() - start;
    }
}
```

This code creates a `DisjointPairs` class that takes an integer array as input and returns the number of disjoint pairs using a Union-Find data structure. It also prints the time taken to check for disjointness between each pair. The example in the main method shows how to use this class with a sample array.']

