```java
import java.util.*;
import java.util.concurrent.TimeUnit;

public class UnionFind {
    private final int[] parents;
    private final int[] ranks;

    public UnionFind(int size) {
        this.parents = new int[size];
        this.ranks = new int[size];
        for (int i = 0; i < size; ++i) {
            parents[i] = i;
            ranks[i] = 1;
        }
    }

    public int find(int x) {
        if (parents[x] != x)
            parents[x] = find(parents[x]);
        return parents[x];
    }

    public void unionComponents(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (ranks[rootX] > ranks[rootY])
                parents[rootY] = rootX;
            else if (ranks[rootX] < ranks[rootY])
                parents[rootX] = rootY;
            else {
                parents[rootY] = rootX;
                ranks[rootX]++;
            }
        }
    }

    public static int countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < arr.length - 1; ++i) {
            for (int j = i + 1; j < arr.length; ++j) {
                int x = uf.find(arr[i]);
                int y = uf.find(arr[j]);
                if (x != y) {
                    uf.unionComponents(x, y);
                }
            }
        }
        long endTime = System.currentTimeMillis();
        int disjointPairs = arr.length - uf.getSetsCount();
        System.out.printf("Disjoint pairs found: %d\n", disjointPairs);
        System.out.printf("Time taken (milliseconds): %.3f\n", endTime - startTime);
        return disjointPairs;
    }
}
```']

