@Component
public class ServiceRestarter implements InitializingBean {
    private static final long RESTART_INTERVAL = TimeUnit.MINUTES.toMillis(60);
    private MyService myService;
    private NotificationService notificationService;

    @Inject
    public ServiceRestarter(MyService myService, NotificationService notificationService) {
        this.myService = myService;
        this.notificationService = notificationService;
    }

    @PostConstruct
    public void start() {
        Thread restartThread = new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(RESTART_INTERVAL);
                } catch (InterruptedException e) {
                    // Handle interruptions gracefully
                }
                if (!myService.isRunning()) {
                    myService.start();
                    notificationService.sendNotification("Service restarted.");
                }
            }
        });
        restartThread.start();
    }

    @PreDestroy
    public void stop() {
        myService.stop();
    }
}
