8. Finally, here's a recursive JavaScript function that traverses a DOM tree and returns elements matching a given selector:

```javascript
function traverse(element, selector, callback) {
    if (callback(element)) return [element];
    if (!element || element.nodeType !== 1) return [];
    let matches = [];
    const children = Array.from(element.children);
    for (let child of children) {
        matches = matches.concat(traverse(child, selector, callback));
    }
    if (!matches.length) return matches;
    const results = matches.filter((el) => el.matches ? el.matches(selector) : el.classList.contains(selector));
    return results.length > 0 ? results : matches.concat(traverse(element.nextElementSibling, selector, callback));
}
```

Usage: `let elements = traverse(document.body, '.my-class');`"]

