['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Xunit;

namespace SecureHashProvider
{
    public class SecureHashProvider : IDisposable
    {
        private readonly HashAlgorithm _hashAlgorithm;
        private readonly MD5 _md5;
        private readonly SHA256 _sha256;
        private readonly string _externalServiceUrl;
        private readonly HttpClient _httpClient;

        public SecureHashProvider(string externalServiceUrl)
        {
            _externalServiceUrl = externalServiceUrl;
            _hashAlgorithm = HashAlgorithm.Create("SHA256");
            _md5 = MD5.Create();
            _sha256 = SHA256.Create();
            _httpClient = new HttpClient();
        }

        public async Task<byte[]> ComputeHashAsync(Stream inputStream, bool useExternalService)
        {
            if (useExternalService && await IsExternalServiceAvailableAsync())
            {
                var request = new HashRequest { Input = inputStream };
                var response = await SendRequestAsync(request);
                return Encoding.UTF8.GetBytes(response.Result);
            }

            using (var memoryStream = new MemoryStream())
            {
                inputStream.CopyTo(memoryStream);
                if (!useExternalService)
                    ComputeHash(memoryStream.ToArray(), _sha256); // Use SHA-256 as default internal hash algorithm
                return memoryStream.ToArray();
            }
        }

        private async Task<bool> IsExternalServiceAvailableAsync()
        {
            try
            {
                await _httpClient.SendAsync(new HttpRequestMessage(HttpMethod.Head, _externalServiceUrl), HttpCompletionOption.ResponseHeadersRead);
