2. Java Function to find disjoint pairs (Only code)

```java
import java.util.*;

public class DisjointPairs {
    private static int[] parents;
    private static int[] ranks;

    public static void initialize(int n) {
        parents = new int[n];
        ranks = new int[n];
        for (int i = 0; i < n; ++i) {
            parents[i] = i;
            ranks[i] = 1;
        }
    }

    public static int find(int x) {
        if (parents[x] != x) parents[x] = find(parents[x]);
        return parents[x];
    }

    public static void unionComponents(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (ranks[rootX] < ranks[rootY]) parents[rootX] = rootY;
            else if (ranks[rootX] > ranks[rootY]) parents[rootY] = rootX;
            else {
                parents[rootY] = rootX;
                ranks[rootX]++;
            }
        }
    }

    public static int countDisjointPairs(int[] arr) {
        initialize(arr.length);
        int pairs = 0;
        for (int i = 0; i < arr.length; ++i) {
            int j = i + 1;
            if ((j >= arr.length || find(arr[i]) != find(arr[j])) && find(i) != find(j)) {
                unionComponents(arr[i], arr[j]);
                pairs++;
            }
        }
        return pairs;
    }
}
