3. PEM Certificate Generator (Only code, Python)

```python
import requests
import base64
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.keys import RSAKey
from cryptography.hazmat.modulus import RSAOAEP
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.serialization import SerializationBio, encode_pem

def get_certificate(oauth_request):
    private_key_url = oauth_request['private_key_url']
    certificate_url = oauth_request['certificate_url']

    private_key_resp = requests.get(private_key_url)
    private_key = RSAKey.from_private_bytes(RSAKey.generate(2048).private_bytes(), backend=default_backend())
    private_key_pem = private_key.private_bytes(encoding=encode_pem, format=serialization.Encoding.PEM, encryption_algorithm=serialization.NoEncryption())

    certificate_resp = requests.get(certificate_url)
    certificate = rsa.RSAPublicNumbers(
        n=base64.b64decode(certificate_resp.content),
        e=int(oauth_request['exponent'])
    )
    certificate_key = RSAKey.from_public_numbers(certificate)
    certificate_pem = certificate_key.public_bytes(encoding=encode_pem, format=serialization.Encoding.PEM)

    return certificate_pem + private_key_pem.decode('utf-8')
