// Union-Find function in C++:

#include <vector>
#include <unordered_map>

template<typename T>
int disjointPairCheck(const std::vector<T>& arr) {
    std::vector<int> parent(arr.size());
    std::unordered_map<T, int> size;
    for (size_t i = 0; i < arr.size(); ++i) {
        parent[i] = i;
        size[arr[i]] = 1;
    }

    auto findSet = [&](int x) -> int {
        if (parent[x] != x) parent[x] = findSet(parent[x]);
        return parent[x];
    };

    std::vector<std::pair<T, T>> pairs;
    for (size_t i = 0; i < arr.size(); ++i) {
        for (size_t j = i + 1; j < arr.size(); ++j) {
            auto x = findSet(i);
            auto y = findSet(j);
            if (x != y) {
                pairs.push_back({arr[i], arr[j]});
                parent[x] = y;
            }
        }
    }

    size_t count = pairs.size();
    std::cout << "Pair check time (ms):" << std::endl;
    for (const auto& pair : pairs) {
        auto start = std::chrono::steady_clock::now();
        findSet(pair.first);
        findSet(pair.second);
        auto end = std::chrono::steady_clock::now();
        std::cout << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ";
    }
    std::cout << std::endl;

    return count;
}

