import os
import rsa
from Cryptodome.PublicKey import RSA
from Cryptodome.Signature import pkcs1_sign
from Cryptodome.Hash import SHA256
from Cryptodome.Transport.TLS import TLSContext, FileTLSAdapter
import base64

def oauth_certificate(req):
    key = rsa.NewKey(3072)
    cert = rsa.newkeys.RSASignCMS(key)
    pem_private = cert.export_key()
    pem_cert = cert.export_certificate()

    with open("privkey.pem", "wb") as priv:
        priv.write(pem_private)

    with open("cert.pem", "wb") as certf:
        certf.write(pem_cert)

    key_file = os.path.join(req["keyfile"], req["key"])
    cert_file = os.path.join(req["certfile"], req["cert"])

    with open(key_file, 'rb') as private_key:
        priv_key = rsa.PrivateKey.load_pkcs1(private_key)

    with open(cert_file, 'rb') as certificate:
        cert_obj = RSA.construct(certificate)

    context = TLSContext()
    tls_sock = FileTLSAdapter.server_side(context, (cert_obj, priv_key))
    with open(req["path"], "rb") as f:
            data = base64.b64decode(f.read())
            signed_data = pkcs1_sign(SHA256.new(data), priv_key, pkcs1_sign.pkcs1_v1_5)
    with open(req["output"], "wb") as output:
        output.write(signed_data + data)

