import java.util.*;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6};
        System.out.println(disjointPairsCount(arr));
    }

    static long disjointPairsCount(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        long timeStart = System.nanoTime();
        long result = 0;
        for (int i = 0; i < arr.length - 1; ++i) {
            long timePairStart = System.nanoTime();
            if (uf.find(i) != uf.find(i + 1)) {
                result++;
            }
            long timePairEnd = System.nanoTime();
            System.out.printf("Check for pair %d-%d took: %.6f ms\n", i, i + 1, TimeUnit.NANOSECONDS.toMillis(timePairEnd - timePairStart));
        }
        long timeEnd = System.nanoTime();
        System.out.printf("Total execution took: %.6f ms\n", TimeUnit.NANOSECONDS.toMillis(timeEnd - timeStart));
        return result;
    }

    static class UnionFind {
        int[] id;

        public UnionFind(int size) {
            id = new int[size];
            for (int i = 0; i < size; ++i) {
                id[i] = i;
            }
        }

        public int find(int x) {
            return id[x] == x ? x : id[x] = find(id[x]);
        }
    }
