**Java Function**:

```java
import java.util.*;

public class DisjointPairCounter {

    public static long countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        long count = 0;
        long startTime, endTime;

        for (int i = 0; i < arr.length; ++i) {
            startTime = System.nanoTime();
            if (uf.find(arr[i]) != uf.find(arr[i] + 1)) {
                count++;
            }
            endTime = System.nanoTime();
            // Print the time taken for each pair check in milliseconds
            System.out.printf("Pair (%d, %d) checked in %.6f ms\n", arr[i], arr[i] + 1, (endTime - startTime) / 1_000_000);
        }

        return count;
    }

    static class UnionFind {

        int[] parent;

        public UnionFind(int size) {
            this.parent = new int[size];
            for (int i = 0; i < size; ++i) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (x != parent[x]) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void unionElements(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA != rootB) {
                parent[rootB] = rootA;
            }
        }
    }
}
```

