    memcpy(&user_accounts[num_user_accounts - 1], user, sizeof(UserAccount));

    pthread_mutex_unlock(&user_accounts_lock);
}

// Function to delete a user account from the in-memory list and external database.
void delete_user(UserAccount *user) {
    pthread_mutex_lock(&user_accounts_lock);

    // Locate the user in the in-memory list
    size_t i;
    for (i = 0; i < num_user_accounts; ++i) {
        if (!strcmp(user->id, user_accounts[i].id)) {
            break;
        }
    }

    if (i == num_user_accounts) {
        pthread_mutex_unlock(&user_accounts_lock);
        return;
    }

    // Copy the user to the end of the list and update the external database asynchronously
    memmove(&user_accounts[i], &user_accounts[i + 1], sizeof(UserAccount) * (num_user_accounts - i - 1));
    --num_user_accounts;
    user_accounts = realloc(user_accounts, sizeof(UserAccount) * num_user_accounts);

    // Call the function to update the external database asynchronously
    (void)store_user(user);

    pthread_mutex_unlock(&user_accounts_lock);
}
