```csharp
using System;
using System.Data;
using System.IO;
using Azure.Storage.Blobs;
using Azure.Storage.Samples.Blob;

public class CloudServiceHelper
{
    private BlobServiceClient _blobServiceClient;

    public CloudServiceHelper(string connectionString)
    {
        _blobServiceClient = new BlobServiceClient(connectionString);
    }

    public DataTableReader UploadAndQuery(byte[] byteArray, string containerName, string query)
    {
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient(containerName);
        var blobName = Guid.NewGuid().ToString();
        var blobClient = blobContainerClient.GetBlobClient(blobName);

        using (var stream = new MemoryStream(byteArray))
            blobClient.Upload(stream, overwrite: true);

        var queryResult = BlobQuery.TableQuery(containerName, query).Execute();
        return queryResult.ToDataTableReader();
    }
}
```']

